    ('04482240-61ec-5aa4-8148-52a6ecb6702e'::uuid, 'Quiz — L’outil de base de la mécanique', 'Sciences de l’ingénieur', '1re', 'Calcul vectoriel et repères', 'ae7b3d2a-42b1-5b71-9478-70dc5cc95bc9'::uuid),
    ('a06954d5-2221-5caf-a422-2f20d43ff88f'::uuid, 'Quiz — Forces, moments et liaisons', 'Sciences de l’ingénieur', '1re', 'Modélisation des actions', 'aeea5e3e-4376-5f58-86db-0a463fb51895'::uuid),
    ('6cbfd9e4-14ce-5608-a79d-667c906e8480'::uuid, 'Quiz — Isoler, inventorier, représenter', 'Sciences de l’ingénieur', '1re', 'Représentation complète des actions', '6322be5a-0769-5dec-98de-22a190eb8c14'::uuid),
    ('17673a92-c5f9-5380-b5ed-fc82feb4e38f'::uuid, 'Quiz — Deux conditions d’équilibre', 'Sciences de l’ingénieur', '1re', 'Principe fondamental de la statique', '0c3158b3-d778-50fb-86be-0e92e2022170'::uuid),
    ('618e654f-b662-5373-abba-6b884e09f199'::uuid, 'Quiz — Rendement d’une chaîne d’énergie', 'Sciences de l’ingénieur', '1re', 'Énergie et puissance', '2d535f29-9d72-5120-816d-25b322ec1a70'::uuid),
    ('09b673ab-ee83-509e-a407-07676f37f581'::uuid, 'Quiz — Position, vitesse, accélération', 'Sciences de l’ingénieur', '1re', 'Cinématique du point', 'baea0cf0-db47-57f5-a1f1-4764ad8415a4'::uuid),
    ('2eb9d35d-9584-5591-8762-b37241e72612'::uuid, 'Quiz — Analogique, numérique, logique', 'Sciences de l’ingénieur', '1re', 'Les signaux', 'e77cec34-28c7-58ce-9855-1ba8b3fa7076'::uuid),
    ('156edf51-37ed-5941-8e94-a84329085f0f'::uuid, 'Quiz — Binaire, hexadécimal et codage des caractères', 'Sciences de l’ingénieur', '1re', 'Codage de l’information', 'efd6923d-2276-5653-a18f-c4ae9eb141ab'::uuid),
    ('b616610f-6745-5c7d-a5da-0280774398c9'::uuid, 'Quiz — NON, ET, OU', 'Sciences de l’ingénieur', '1re', 'Les opérateurs logiques fondamentaux', '26568682-fac7-5738-9dd2-2303cd650a03'::uuid),
    ('1d37372b-a673-57c6-8725-33ec7968e889'::uuid, 'Quiz — Du cahier des charges au logigramme', 'Sciences de l’ingénieur', '1re', 'Association de portes logiques', 'ee42dbc2-b343-51a5-8e18-e337b9ca0d67'::uuid),
    ('2899dea6-971c-5b9a-a19a-6894026b7f2f'::uuid, 'Quiz — Les règles du calcul logique', 'Sciences de l’ingénieur', '1re', 'Algèbre de Boole', 'cdf57708-087b-592d-a14b-daa5677be935'::uuid),
    ('a6785078-95fc-51cc-8baa-eea079307d22'::uuid, 'Quiz — Moins de portes, moins de coût', 'Sciences de l’ingénieur', '1re', 'Simplification des expressions logiques', '108deac9-8df9-52aa-bcaa-74c26bfcf375'::uuid),
    ('6e545dd4-12cc-565f-85e7-a076d1ae674c'::uuid, 'Quiz — Intégrité, confidentialité, disponibilité', 'Sciences de l’ingénieur', '1re', 'Sécurité du transfert d’information', '1cd56114-93b3-5083-8aba-a43fac5914d0'::uuid),
    ('234b91e3-be5e-5777-b4e5-60466328693f'::uuid, 'Quiz — Adresses, protocoles et topologies', 'Sciences de l’ingénieur', '1re', 'Réseau de données', 'a601a8b1-89dd-5bff-a75f-ada4c5127551'::uuid),
    ('979cbc2b-1f29-5499-8e65-edb96b712d4a'::uuid, 'Quiz — Lois des mailles et des nœuds', 'Sciences de l’ingénieur', '1re', 'Le circuit électrique', '1f22149f-245f-56d5-8448-d85c99eb4965'::uuid),
    ('7b0ec4f9-93c5-565a-82dd-7dfc8eccf36a'::uuid, 'Quiz — Trois dipôles, trois comportements', 'Sciences de l’ingénieur', '1re', 'Les composants électriques : générateur, résistance et condensateur', '0310837a-a704-5166-ab1f-9c8a0ac846b1'::uuid),
    ('ab225d5d-6ba6-5af7-b568-c8cb6cb8306d'::uuid, 'Quiz — Bobine, redressement et commutation', 'Sciences de l’ingénieur', '1re', 'Les composants électriques : inductance, diode et transistor', '79704a60-5635-5c22-a6b3-82dc90f3da64'::uuid),
    ('2f824104-6f9e-5d3c-8cf4-c5a49b46e663'::uuid, 'Quiz — Mesurer, simuler, comparer', 'Sciences de l’ingénieur', '1re', 'Les outils d’étude', 'dddfb511-9afa-5ff1-9a00-78eeabeae139'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('a9196006-968d-5b24-927e-da5d6ecf0a9d'::uuid, '91890217-6547-5d47-8874-55625fd74a35'::uuid, 'Quelles sont les trois contraintes du triangle du projet ?', 'mcq', '["Le coût, le délai et la qualité","Le besoin, la solution et le client","L’étude, la production et la vente","La conception, la réalisation et la validation"]'::jsonb, 0, 'Améliorer l’une pèse toujours sur les deux autres.', 1),
    ('ec4675a8-d496-56c5-a560-5899139ad4b3'::uuid, '91890217-6547-5d47-8874-55625fd74a35'::uuid, 'Que décrit un cahier des charges fonctionnel ?', 'mcq', '["Les fonctions attendues du produit, pas les solutions techniques","Le plan de fabrication détaillé","La liste des composants à acheter","Le planning de l’équipe"]'::jsonb, 0, 'Il dit ce qu’il faut faire, jamais comment le faire.', 2),
    ('71953765-8150-5fe3-b93c-3cdf50f7d71d'::uuid, '91890217-6547-5d47-8874-55625fd74a35'::uuid, '« Le produit doit être solide » est une exigence correctement formulée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il manque un critère, un niveau et une flexibilité mesurables.', 3),
    ('6a8fc00e-25ea-51bf-88d6-707be9553dea'::uuid, '91890217-6547-5d47-8874-55625fd74a35'::uuid, 'Qu’est-ce qu’une fonction contrainte ?', 'mcq', '["Une limite imposée par le milieu extérieur au produit","La raison d’être du produit","Une panne prévisible","Un coût de fabrication"]'::jsonb, 0, 'Normes, encombrement, température : elle borne les solutions possibles.', 4),
    ('c0415b41-eb97-5f77-b118-cc5d413620e0'::uuid, '91890217-6547-5d47-8874-55625fd74a35'::uuid, 'Qu’est-ce qu’un jalon dans un projet ?', 'mcq', '["Un point de décision qui clôt une phase","Une tâche de longue durée","Un membre de l’équipe projet","Un livrable intermédiaire sans décision"]'::jsonb, 0, 'On y décide de poursuivre, de corriger ou d’arrêter.', 5),
    ('ad327ade-244b-52ec-be0c-2f32edf7069d'::uuid, '91890217-6547-5d47-8874-55625fd74a35'::uuid, 'Quelles sont les quatre phases du cycle de vie d’un projet ?', 'mcq', '["Conception, planification, réalisation, terminaison","Analyse, achat, montage, vente","Besoin, prototype, série, maintenance","Étude, essai, correction, livraison"]'::jsonb, 0, 'Chacune se clôt par un jalon.', 6),
    ('f5599827-7821-5b96-a5f6-7f433a7f896e'::uuid, '91890217-6547-5d47-8874-55625fd74a35'::uuid, 'Un projet se répète à l’identique, comme une production en série.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est par définition unique et borné dans le temps.', 7),
    ('c60a610e-a31f-5ce1-b0ee-e212446a6ae2'::uuid, '91890217-6547-5d47-8874-55625fd74a35'::uuid, 'Quels écarts la démarche de l’ingénieur analyse-t-elle ?', 'mcq', '["Entre cahier des charges, modèle et réel mesuré","Entre coût prévu et coût réel uniquement","Entre équipes","Entre fournisseurs"]'::jsonb, 0, 'Ces trois écarts servent à valider ou à corriger produit et modèle.', 8),
    ('2126d2a6-1ee4-569a-b5a6-bf21b57c88a2'::uuid, '34655a10-42d4-51e4-9295-c7b5bac90c35'::uuid, 'Que produit la phase de conception ?', 'mcq', '["Des solutions techniques répondant au besoin","Le planning détaillé du projet","Le produit fini","Le bilan financier"]'::jsonb, 0, 'Elle décline les fonctions en solutions constructives.', 1),
    ('049351ce-5283-5656-af0e-70cd32a2efb1'::uuid, '34655a10-42d4-51e4-9295-c7b5bac90c35'::uuid, 'Que faut-il éviter pendant la phase de divergence ?', 'mcq', '["Juger et écarter les idées","Produire beaucoup d’idées","Utiliser des analogies","Noter toutes les propositions"]'::jsonb, 0, 'Juger trop tôt tue les idées fragiles.', 2),
    ('67917129-0774-5d65-b482-a2a5b2483ca9'::uuid, '34655a10-42d4-51e4-9295-c7b5bac90c35'::uuid, 'Un tableau multicritère donne la solution objectivement optimale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il rend le choix explicite et discutable : changer les poids change le classement.', 3),
    ('8df2df56-c155-5f4b-b71d-1b2dacb0af42'::uuid, '34655a10-42d4-51e4-9295-c7b5bac90c35'::uuid, 'À quoi sert une maquette numérique en conception ?', 'mcq', '["À vérifier encombrement, interférences et montage avant fabrication","À calculer le prix de vente","À rédiger le cahier des charges","À planifier les tâches"]'::jsonb, 0, 'Elle évite de découvrir un défaut au moment de l’assemblage.', 4),
    ('b75eba1a-2997-5721-8260-9d25893302bd'::uuid, '34655a10-42d4-51e4-9295-c7b5bac90c35'::uuid, 'Pourquoi faut-il expliciter les hypothèses d’une simulation ?', 'mcq', '["Parce qu’un résultat de simulation n’a de sens que dans le cadre de ses hypothèses","Pour allonger le rapport","Parce que la norme l’impose","Pour justifier le coût du logiciel"]'::jsonb, 0, 'Solide indéformable, frottements négligés : chacune borne la validité.', 5),
    ('51d3cce3-b4ee-5329-8b81-9114b23ae2c4'::uuid, '34655a10-42d4-51e4-9295-c7b5bac90c35'::uuid, 'La phase de conception engage l’essentiel du coût final du produit.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle le décide alors que presque rien n’a encore été dépensé.', 6),
    ('8a8a692b-43cd-55bc-97b7-4ca4b7339a30'::uuid, '34655a10-42d4-51e4-9295-c7b5bac90c35'::uuid, 'Qu’est-ce qu’une fonction technique ?', 'mcq', '["La déclinaison interne d’une fonction de service","Une contrainte du milieu extérieur","Un composant du commerce","Un critère de coût"]'::jsonb, 0, 'Elle se traduit ensuite en solution constructive.', 7),
    ('7c76e590-0872-58f4-b88f-9a9f2c1dcd8c'::uuid, '34655a10-42d4-51e4-9295-c7b5bac90c35'::uuid, 'À quoi sert le prototypage rapide ?', 'mcq', '["À éprouver une solution avant de s’engager","À produire la série définitive","À archiver le projet","À former les utilisateurs"]'::jsonb, 0, 'Il réduit le risque d’un mauvais choix de conception.', 8),
    ('1f0a8772-68a5-53a7-9cc8-d2c5616bb7d8'::uuid, 'c88578ee-c6b3-5412-bae2-92c467f7fdbd'::uuid, 'Qu’est-ce que le chemin critique d’un projet ?', 'mcq', '["La suite des tâches de marge nulle, qui fixe la durée minimale du projet","La tâche la plus coûteuse","La tâche la plus longue","La suite des tâches les plus risquées"]'::jsonb, 0, 'Tout retard sur l’une d’elles retarde le projet entier.', 1),
    ('bc9817a5-8204-5f8a-ae1b-10f62ab37a06'::uuid, 'c88578ee-c6b3-5412-bae2-92c467f7fdbd'::uuid, 'Accélérer une tâche hors du chemin critique raccourcit le projet.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle dispose d’une marge : le projet n’y gagne aucun jour.', 2),
    ('ea575a2a-0ee1-5811-be30-82f75dbb419e'::uuid, 'c88578ee-c6b3-5412-bae2-92c467f7fdbd'::uuid, 'Que représente un diagramme de Gantt ?', 'mcq', '["Les tâches sous forme de rectangles dont la longueur est proportionnelle à la durée","Le réseau des antériorités uniquement","Le budget par poste","L’organigramme de l’équipe"]'::jsonb, 0, 'C’est l’outil de suivi le plus lisible.', 3),
    ('99ab8959-d055-5343-91a8-3f8c0beda4e8'::uuid, 'c88578ee-c6b3-5412-bae2-92c467f7fdbd'::uuid, 'Qu’est-ce que la marge d’une tâche ?', 'mcq', '["L’écart entre sa date au plus tard et sa date au plus tôt","Son coût supplémentaire","Sa durée totale","Le nombre de personnes qui y travaillent"]'::jsonb, 0, 'Une marge nulle place la tâche sur le chemin critique.', 4),
    ('bb327367-0564-5397-89d2-d6f86646338f'::uuid, 'c88578ee-c6b3-5412-bae2-92c467f7fdbd'::uuid, 'Qu’appelle-t-on antériorité d’une tâche ?', 'mcq', '["Les tâches qui doivent être achevées avant qu’elle commence","Sa date de fin","Sa durée estimée","Son coût prévisionnel"]'::jsonb, 0, 'C’est ce qui structure le réseau PERT.', 5),
    ('2f66b56c-775a-5a39-8ab3-583d95482323'::uuid, 'c88578ee-c6b3-5412-bae2-92c467f7fdbd'::uuid, 'Comment calcule-t-on les dates au plus tard dans un réseau PERT ?', 'mcq', '["En parcourant le réseau de la fin vers le début","En parcourant le réseau du début vers la fin","En additionnant toutes les durées","En prenant la moyenne des durées"]'::jsonb, 0, 'Les dates au plus tôt se calculent, elles, en parcours avant.', 6),
    ('125c9912-34c4-55f7-86dc-b88c690deb52'::uuid, 'c88578ee-c6b3-5412-bae2-92c467f7fdbd'::uuid, 'Le lissage des ressources consiste à décaler des tâches disposant d’une marge.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il évite les pics de charge sans allonger le projet.', 7),
    ('27e936a4-8ddd-58bb-aaa1-7856cfe6e81e'::uuid, 'c88578ee-c6b3-5412-bae2-92c467f7fdbd'::uuid, 'Que faire si une tâche du chemin critique prend du retard ?', 'mcq', '["Arbitrer : ajouter des moyens, réduire le périmètre ou accepter le décalage","Attendre la fin du projet","Réaffecter les marges des autres tâches","Supprimer la tâche"]'::jsonb, 0, 'Le retard se répercute intégralement sur la fin du projet.', 8),
    ('0d325e48-0255-5b6c-8ceb-3cfb6c738b0a'::uuid, 'df199d78-612b-548c-9260-ae383c4db49f'::uuid, 'Quelle est la différence entre vérifier et valider ?', 'mcq', '["Vérifier : conforme aux spécifications ; valider : répond au besoin réel","Ce sont deux synonymes","Vérifier concerne le coût, valider la qualité","Vérifier se fait après la livraison"]'::jsonb, 0, '« A-t-on bien construit le produit ? » contre « a-t-on construit le bon produit ? ».', 1),
    ('385cbed5-dfe2-5b92-9201-4a3a9b94ac79'::uuid, 'df199d78-612b-548c-9260-ae383c4db49f'::uuid, 'Un produit conforme à ses spécifications répond nécessairement au besoin.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Si la spécification traduisait mal le besoin, le produit est vérifié mais invalide.', 2),
    ('a0e22020-10cc-5461-8078-cbbd400e15b1'::uuid, 'df199d78-612b-548c-9260-ae383c4db49f'::uuid, 'Que comprend la phase de terminaison ?', 'mcq', '["Livraison, documentation, bilan et retour d’expérience","La fabrication des pièces","La recherche de solutions","Le calcul du chemin critique"]'::jsonb, 0, 'C’est aussi le moment de l’archivage et de la dissolution de l’équipe.', 3),
    ('f28590d3-bcd3-5e39-8009-e1b9e9cd9fe8'::uuid, 'df199d78-612b-548c-9260-ae383c4db49f'::uuid, 'Pourquoi tracer les modifications en cours de réalisation ?', 'mcq', '["Pour éviter que le projet dérive sans qu’on sache pourquoi","Pour allonger la documentation","Pour retarder la livraison","Parce que le client l’exige toujours"]'::jsonb, 0, 'Toute évolution doit être tracée, chiffrée et validée.', 4),
    ('826ee38e-3f5c-57d1-8960-ab7ef3de98ff'::uuid, 'df199d78-612b-548c-9260-ae383c4db49f'::uuid, 'Que faire d’un écart entre performance mesurée et cahier des charges ?', 'mcq', '["L’analyser : produit, protocole de mesure ou hypothèses du modèle","L’ignorer s’il est faible","Modifier le cahier des charges","Recommencer la conception"]'::jsonb, 0, 'C’est le raisonnement central attendu en sciences de l’ingénieur.', 5),
    ('e81c0091-9a25-529d-b46e-f2d3d6effec4'::uuid, 'df199d78-612b-548c-9260-ae383c4db49f'::uuid, 'Le retour d’expérience bénéficie surtout aux projets suivants.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est pourquoi il est si souvent sacrifié, à tort.', 6),
    ('67daef75-d275-5e6d-9048-0f9560bc8c4e'::uuid, 'df199d78-612b-548c-9260-ae383c4db49f'::uuid, 'Qu’est-ce que la recette d’un projet ?', 'mcq', '["La vérification contradictoire du produit livré avec le client","La liste des composants","Le budget consommé","Le planning réel"]'::jsonb, 0, 'Elle conditionne l’acceptation formelle de la livraison.', 7),
    ('1eb16bb6-96d1-5c28-bcfa-5bd67a4c8a8f'::uuid, 'df199d78-612b-548c-9260-ae383c4db49f'::uuid, 'Que compare le suivi d’avancement ?', 'mcq', '["L’état réel du projet à son prévisionnel","Deux solutions techniques","Le produit et son concurrent","Les hypothèses du modèle"]'::jsonb, 0, 'Il permet de réagir avant que l’écart devienne irrattrapable.', 8),
    ('6b37dea4-b0d7-5489-887c-9bf357025ea0'::uuid, '67f9f464-a5df-58ef-b943-abc84f3f6599'::uuid, 'Que décrit un diagramme de cas d’utilisation ?', 'mcq', '["Les acteurs extérieurs et les services que le système leur rend","La structure interne du système","Les états successifs du système","Le planning du projet"]'::jsonb, 0, 'Il répond à la question du besoin, pas à celle de la structure.', 1),
    ('08df2960-2a8b-54cc-b0cb-fd61071f98f3'::uuid, '67f9f464-a5df-58ef-b943-abc84f3f6599'::uuid, 'Quel diagramme SysML montre les flux échangés entre les blocs ?', 'mcq', '["Le diagramme de blocs internes","Le diagramme des exigences","Le diagramme d’états","Le diagramme de séquence"]'::jsonb, 0, 'Matière, énergie et information y circulent par des ports.', 2),
    ('85d42024-5d3e-50b6-ba64-24421c8cdeb7'::uuid, '67f9f464-a5df-58ef-b943-abc84f3f6599'::uuid, 'Un diagramme d’états décrit les transitions déclenchées par des événements.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Chaque transition peut être soumise à une condition de garde.', 3),
    ('42ccf9b0-5b5c-5e3e-ab17-3a7d47ce39ca'::uuid, '67f9f464-a5df-58ef-b943-abc84f3f6599'::uuid, 'Quels sont les maillons de la chaîne d’énergie ?', 'mcq', '["Alimenter, distribuer, convertir, transmettre, agir","Acquérir, traiter, communiquer","Analyser, modéliser, expérimenter","Capter, calculer, afficher"]'::jsonb, 0, 'La chaîne d’information, elle, acquiert, traite et communique.', 4),
    ('7f9c72b9-5ba2-5922-8744-40daaf017d4a'::uuid, '67f9f464-a5df-58ef-b943-abc84f3f6599'::uuid, 'Quel composant réalise la fonction « acquérir » de la chaîne d’information ?', 'mcq', '["Le capteur","L’actionneur","Le préactionneur","Le réducteur"]'::jsonb, 0, 'Il transforme une grandeur physique en signal exploitable.', 5),
    ('280a3c80-ba46-5460-920d-34d664ef9515'::uuid, '67f9f464-a5df-58ef-b943-abc84f3f6599'::uuid, 'Un modèle doit représenter fidèlement toute la réalité du système.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il n’en retient que ce qui est utile à la question posée.', 6),
    ('434fbfe0-151c-5c56-a23f-74a1d63b89fd'::uuid, '67f9f464-a5df-58ef-b943-abc84f3f6599'::uuid, 'À quoi sert le diagramme des exigences ?', 'mcq', '["À porter la traçabilité du cahier des charges sous forme d’arbre","À décrire la géométrie des pièces","À planifier les tâches","À simuler le comportement mécanique"]'::jsonb, 0, 'Chaque exigence y est identifiée, formulée et vérifiable.', 7),
    ('83886959-e04d-5708-b2bb-4b48ee33c00f'::uuid, '67f9f464-a5df-58ef-b943-abc84f3f6599'::uuid, 'Qu’est-ce qui fait d’un système un système asservi ?', 'mcq', '["La mesure de la sortie revient commander l’entrée","Il possède un moteur","Il est programmé","Il consomme peu d’énergie"]'::jsonb, 0, 'C’est le bouclage par le capteur qui le caractérise.', 8),
    ('e78c3f75-b3d4-5ac7-884b-41c72c22ef56'::uuid, '04482240-61ec-5aa4-8148-52a6ecb6702e'::uuid, 'Quelles sont les quatre caractéristiques d’un vecteur force ?', 'mcq', '["Point d’application, direction, sens et norme","Masse, vitesse, accélération et temps","Longueur, largeur, hauteur et masse","Origine, extrémité, couleur et unité"]'::jsonb, 0, 'Deux vecteurs sont égaux si direction, sens et norme coïncident.', 1),
    ('32ac2cc2-16d3-535e-95f3-80b4999d1fd8'::uuid, '04482240-61ec-5aa4-8148-52a6ecb6702e'::uuid, 'Quelle est la composante d’une force le long d’un axe avec lequel elle fait l’angle α ?', 'mcq', '["F × cos α","F × sin α","F × tan α","F / cos α"]'::jsonb, 0, 'La composante perpendiculaire vaut F × sin α.', 2),
    ('ccd57245-56a0-5beb-95b2-ab8e474d7559'::uuid, '04482240-61ec-5aa4-8148-52a6ecb6702e'::uuid, 'Un même vecteur a les mêmes coordonnées dans tous les repères.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les coordonnées changent, le vecteur reste le même.', 3),
    ('3524496a-d970-5dec-a97c-0b0ff5683ff5'::uuid, '04482240-61ec-5aa4-8148-52a6ecb6702e'::uuid, 'À quoi sert le produit vectoriel en mécanique ?', 'mcq', '["Au calcul des moments","Au calcul du travail","Au calcul de la norme","Au calcul de la masse"]'::jsonb, 0, 'Le produit scalaire, lui, sert au calcul du travail d’une force.', 4),
    ('dd7495c8-b0c8-50a8-a54c-bca40ea1cf8c'::uuid, '04482240-61ec-5aa4-8148-52a6ecb6702e'::uuid, 'Que vaut le produit scalaire de deux vecteurs perpendiculaires ?', 'mcq', '["Zéro","Le produit de leurs normes","Un","Leur somme"]'::jsonb, 0, 'Parce que le cosinus d’un angle droit est nul.', 5),
    ('86747eeb-f02e-566c-b75c-7ec2be0d2e58'::uuid, '04482240-61ec-5aa4-8148-52a6ecb6702e'::uuid, 'Comment choisit-on un repère en mécanique ?', 'mcq', '["De façon à simplifier les calculs, par exemple selon un plan incliné","Toujours horizontal et vertical","Toujours centré sur la Terre","Au hasard"]'::jsonb, 0, 'C’est un choix de commodité, non de physique.', 6),
    ('912c67e2-4878-5ef3-97d3-1d108dd858c2'::uuid, '04482240-61ec-5aa4-8148-52a6ecb6702e'::uuid, 'Comment calcule-t-on la norme d’un vecteur de coordonnées (x ; y) ?', 'mcq', '["√(x² + y²)","x + y","|x| + |y|","x × y"]'::jsonb, 0, 'C’est le théorème de Pythagore appliqué aux composantes.', 7),
    ('3b804af6-8453-5e02-8331-6feb90bd9a38'::uuid, '04482240-61ec-5aa4-8148-52a6ecb6702e'::uuid, 'Multiplier un vecteur par un réel négatif inverse son sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et multiplie sa norme par la valeur absolue du réel.', 8),
    ('ab144b79-8adf-514c-bcae-972d5e088b96'::uuid, 'a06954d5-2221-5caf-a422-2f20d43ff88f'::uuid, 'Quelle est l’unité d’un moment ?', 'mcq', '["Le newton-mètre","Le newton","Le joule","Le pascal"]'::jsonb, 0, 'Il mesure l’aptitude d’une force à faire tourner un solide.', 1),
    ('272eab23-2a95-5c4a-9824-3c8417b7cf09'::uuid, 'a06954d5-2221-5caf-a422-2f20d43ff88f'::uuid, 'Que vaut le moment d’une force dont la droite d’action passe par le point considéré ?', 'mcq', '["Zéro","Le produit F × d","La force elle-même","L’infini"]'::jsonb, 0, 'Le bras de levier est nul, quelle que soit l’intensité de la force.', 2),
    ('9fca574b-d230-51b9-bb0b-07eecb028786'::uuid, 'a06954d5-2221-5caf-a422-2f20d43ff88f'::uuid, 'Qu’est-ce que le bras de levier ?', 'mcq', '["La distance perpendiculaire entre la droite d’action et le point considéré","La longueur du solide","La distance entre les deux extrémités de la force","La hauteur du point d’application"]'::jsonb, 0, 'L’allonger permet d’obtenir un grand moment avec une petite force.', 3),
    ('f01e302c-56b5-5ac0-a071-fdb530551ddc'::uuid, 'a06954d5-2221-5caf-a422-2f20d43ff88f'::uuid, 'Combien de degrés de liberté autorise une liaison pivot ?', 'mcq', '["Un, en rotation","Un, en translation","Zéro","Deux"]'::jsonb, 0, 'C’est la liaison réalisée par un roulement à billes.', 4),
    ('7282d67e-9e0f-5676-98a5-3e169b6b2ece'::uuid, 'a06954d5-2221-5caf-a422-2f20d43ff88f'::uuid, 'Un encastrement autorise une rotation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il supprime les six degrés de liberté et transmet tout.', 5),
    ('922c7b08-82e6-5aa0-a09f-b608bd2aa186'::uuid, 'a06954d5-2221-5caf-a422-2f20d43ff88f'::uuid, 'Où s’applique le poids d’un solide ?', 'mcq', '["Au centre de gravité","Au point de contact avec le sol","Au centre géométrique toujours","Au point le plus bas"]'::jsonb, 0, 'C’est une action à distance, de valeur m × g.', 6),
    ('9676ac4f-974e-503b-8a1e-68ceaf61a82f'::uuid, 'a06954d5-2221-5caf-a422-2f20d43ff88f'::uuid, 'Combien de degrés de liberté un solide libre possède-t-il dans l’espace ?', 'mcq', '["Six","Trois","Deux","Un"]'::jsonb, 0, 'Trois translations et trois rotations.', 7),
    ('44f673e4-910a-596b-849c-078b1de670ca'::uuid, 'a06954d5-2221-5caf-a422-2f20d43ff88f'::uuid, 'Une liaison parfaite est une hypothèse de modélisation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle suppose ni jeu ni frottement : il faut la nommer comme hypothèse.', 8),
    ('9505f04f-6cca-5a6f-abcd-e04ffdd81f33'::uuid, '6cbfd9e4-14ce-5608-a79d-667c906e8480'::uuid, 'Que signifie « isoler un solide » ?', 'mcq', '["Le séparer de son environnement et remplacer chaque élément retiré par son action","Le poser sur un support isolant","Le retirer du système","Négliger son poids"]'::jsonb, 0, 'C’est le geste préalable à tout calcul de statique.', 1),
    ('211b9bf9-863f-5e4d-92b7-d38a7909292e'::uuid, '6cbfd9e4-14ce-5608-a79d-667c906e8480'::uuid, 'Les actions intérieures au solide isolé figurent-elles dans le bilan ?', 'mcq', '["Non, jamais","Oui, toujours","Oui, si elles sont grandes","Oui, en dernier"]'::jsonb, 0, 'On ne compte que ce qui traverse la frontière de l’isolement.', 2),
    ('6e556f0f-af0e-5034-a6e4-a467f2d03c05'::uuid, '6cbfd9e4-14ce-5608-a79d-667c906e8480'::uuid, 'De quoi se compose la représentation complète d’une action mécanique ?', 'mcq', '["D’une résultante et d’un moment résultant en un point","D’une force seule","D’un moment seul","D’une masse et d’une accélération"]'::jsonb, 0, 'C’est le torseur d’action mécanique.', 3),
    ('c60ba947-ecc0-5fd0-92b1-02d3a23d66ec'::uuid, '6cbfd9e4-14ce-5608-a79d-667c906e8480'::uuid, 'Quand on transporte un torseur d’un point à un autre, la résultante change.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La résultante est invariante ; c’est le MOMENT qui change.', 4),
    ('2877c762-59ca-58ff-9b4a-7be2d93bfcb8'::uuid, '6cbfd9e4-14ce-5608-a79d-667c906e8480'::uuid, 'Un solide en équilibre sous l’action de deux forces : que peut-on dire ?', 'mcq', '["Même droite d’action, sens opposés, même intensité","Elles sont perpendiculaires","Elles sont concourantes en trois points","Leur somme vaut le poids"]'::jsonb, 0, 'C’est le cas le plus simple, et le plus utile.', 5),
    ('9f6b39cf-abc4-578d-9148-669a1dc776fa'::uuid, '6cbfd9e4-14ce-5608-a79d-667c906e8480'::uuid, 'Que peut-on dire de trois forces non parallèles maintenant un solide en équilibre ?', 'mcq', '["Leurs droites d’action sont concourantes et leur somme vectorielle est nulle","Elles sont toutes égales","Elles sont perpendiculaires deux à deux","Deux d’entre elles se compensent"]'::jsonb, 0, 'Le triangle des forces se ferme : une résolution graphique est possible.', 6),
    ('d7ea6a40-c4cf-5599-8ee4-730e38df2b31'::uuid, '6cbfd9e4-14ce-5608-a79d-667c906e8480'::uuid, 'Combien de composantes une action mécanique possède-t-elle dans un problème plan ?', 'mcq', '["Trois","Six","Deux","Une"]'::jsonb, 0, 'Deux composantes de force et une de moment.', 7),
    ('49ca2d1c-e943-5ac8-8a45-238893a3050c'::uuid, '6cbfd9e4-14ce-5608-a79d-667c906e8480'::uuid, 'Une inconnue tracée dans le mauvais sens rend le calcul faux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le résultat sort simplement négatif : le sens réel est l’inverse du sens supposé.', 8),
    ('ba41b214-a985-53f0-a613-58f61440df04'::uuid, '17673a92-c5f9-5380-b5ed-fc82feb4e38f'::uuid, 'Quelles sont les deux conditions d’équilibre d’un solide ?', 'mcq', '["Somme des forces nulle et somme des moments nulle en un même point","Somme des forces nulle seulement","Somme des moments nulle seulement","Vitesse nulle et accélération nulle"]'::jsonb, 0, 'Les deux sont nécessaires et doivent être vérifiées simultanément.', 1),
    ('ecec92ec-a117-577c-9cef-ccae3fa1b785'::uuid, '17673a92-c5f9-5380-b5ed-fc82feb4e38f'::uuid, 'Deux forces égales et opposées mais non alignées maintiennent un solide en équilibre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles forment un COUPLE : la somme est nulle, mais le solide tourne.', 2),
    ('454f84cb-d309-56e7-bb05-8d9cab2f4096'::uuid, '17673a92-c5f9-5380-b5ed-fc82feb4e38f'::uuid, 'Combien d’équations scalaires le principe fondamental fournit-il dans un problème plan ?', 'mcq', '["Trois","Deux","Six","Une"]'::jsonb, 0, 'Deux de forces et une de moment : donc trois inconnues au plus.', 3),
    ('0b29fa28-9967-5a0e-9e57-bca61c880e50'::uuid, '17673a92-c5f9-5380-b5ed-fc82feb4e38f'::uuid, 'Comment choisir judicieusement le point de calcul des moments ?', 'mcq', '["Là où passent le plus d’inconnues, pour les éliminer","Toujours au centre de gravité","Toujours à l’origine du repère","Au hasard, cela ne change rien"]'::jsonb, 0, 'Une force dont la droite d’action passe par le point a un moment nul.', 4),
    ('63810de6-cd8e-5d4b-b6d6-46f45afd7630'::uuid, '17673a92-c5f9-5380-b5ed-fc82feb4e38f'::uuid, 'Qu’est-ce qu’un système hyperstatique ?', 'mcq', '["Un système comportant plus d’inconnues que d’équations disponibles","Un système en mouvement","Un système sans frottement","Un système soumis à trois forces"]'::jsonb, 0, 'Sa résolution exige des hypothèses supplémentaires.', 5),
    ('f4ec3ef9-f9c5-5610-bab1-00cb0d120218'::uuid, '17673a92-c5f9-5380-b5ed-fc82feb4e38f'::uuid, 'Quelle est la condition de non-glissement au contact ?', 'mcq', '["T ≤ f × N","T ≥ f × N","T = N","T = 0"]'::jsonb, 0, 'f est le coefficient de frottement, N la composante normale.', 6),
    ('370a529c-d1d0-58f1-bee7-e6f874dcfd9a'::uuid, '17673a92-c5f9-5380-b5ed-fc82feb4e38f'::uuid, 'La composante tangentielle du contact s’ajuste tant que le solide ne glisse pas.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle équilibre les autres actions jusqu’à atteindre sa valeur limite.', 7),
    ('4a70e10e-26ce-5bd5-8c2d-7181b0bd827a'::uuid, '17673a92-c5f9-5380-b5ed-fc82feb4e38f'::uuid, 'Que vérifie-t-on à la fin d’une résolution de statique ?', 'mcq', '["L’homogénéité et la vraisemblance des résultats","La couleur des pièces","Le coût du montage","Le nombre de liaisons"]'::jsonb, 0, 'Une intensité en mètres ou une force de 10⁶ N signale une erreur.', 8),
    ('07768d49-8376-54fd-9171-154c2b78c7c6'::uuid, '618e654f-b662-5373-abba-6b884e09f199'::uuid, 'Quelle relation lie puissance et énergie ?', 'mcq', '["P = E / Δt","P = E × Δt","E = P / Δt","P = E + Δt"]'::jsonb, 0, 'La puissance est un débit d’énergie, en watts.', 1),
    ('0145eff8-f52a-5d9d-bbc2-2c6a7896a1af'::uuid, '618e654f-b662-5373-abba-6b884e09f199'::uuid, 'Quelle est l’expression de la puissance mécanique en rotation ?', 'mcq', '["P = C × ω","P = F × v","P = U × I","P = C / ω"]'::jsonb, 0, 'Le couple en N·m multiplié par la vitesse angulaire en rad/s.', 2),
    ('9ae6eec0-78da-5213-ad15-e7e9bcfd5855'::uuid, '618e654f-b662-5373-abba-6b884e09f199'::uuid, 'Comment se combinent les rendements des maillons successifs d’une chaîne ?', 'mcq', '["Ils se multiplient","Ils s’additionnent","On prend le plus grand","On fait leur moyenne"]'::jsonb, 0, 'Trois maillons à 90 % donnent environ 73 % au total.', 3),
    ('e62ab444-73aa-5f06-9f68-e47ac4267ba8'::uuid, '618e654f-b662-5373-abba-6b884e09f199'::uuid, 'Un rendement peut-il dépasser 1 ?', 'mcq', '["Non, jamais","Oui, avec un moteur performant","Oui, en régime transitoire","Oui, si le système stocke de l’énergie"]'::jsonb, 0, 'La puissance utile ne peut excéder la puissance absorbée.', 4),
    ('ede156e5-3723-5fb4-8590-1027eae008c5'::uuid, '618e654f-b662-5373-abba-6b884e09f199'::uuid, 'Comment convertit-on une vitesse en tours par minute en radians par seconde ?', 'mcq', '["ω = 2π × N / 60","ω = N / 60","ω = 2π × N","ω = 60 × N / 2π"]'::jsonb, 0, 'Conversion demandée à presque chaque exercice de puissance.', 5),
    ('e7e57126-e498-56c8-aca9-68d86fa19694'::uuid, '618e654f-b662-5373-abba-6b884e09f199'::uuid, 'Quelle est l’expression de la puissance mécanique en translation ?', 'mcq', '["P = F × v","P = F / v","P = C × ω","P = F × d"]'::jsonb, 0, 'Une force multipliée par une vitesse.', 6),
    ('65dba88d-9c14-5caa-b005-149bd54a4c18'::uuid, '618e654f-b662-5373-abba-6b884e09f199'::uuid, 'Pour améliorer le rendement global, il faut d’abord agir sur le maillon le plus mauvais.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un maillon à 50 % plafonne tout le reste de la chaîne.', 7),
    ('b7f70b6d-9fd6-5761-a551-28c1e859f60f'::uuid, '618e654f-b662-5373-abba-6b884e09f199'::uuid, 'Où partent les pertes dans une chaîne d’énergie ?', 'mcq', '["En effet Joule, frottements, échauffement et bruit","Elles disparaissent","Elles reviennent à la source","Elles augmentent la puissance utile"]'::jsonb, 0, 'Elles sont dégradées, principalement en chaleur.', 8),
    ('30674954-bb44-59d3-82e4-365a779aa754'::uuid, '09b673ab-ee83-509e-a407-07676f37f581'::uuid, 'Qu’étudie la cinématique ?', 'mcq', '["Les mouvements sans se préoccuper de leurs causes","Les forces qui provoquent les mouvements","L’énergie des systèmes","Les déformations des solides"]'::jsonb, 0, 'C’est la dynamique qui relie mouvements et forces.', 1),
    ('0601d2ed-4ae2-58c7-a614-743121b9b02c'::uuid, '09b673ab-ee83-509e-a407-07676f37f581'::uuid, 'Quelle relation lie vitesse linéaire et vitesse angulaire ?', 'mcq', '["v = ω × R","v = ω / R","v = R / ω","v = ω × R²"]'::jsonb, 0, 'R est la distance du point à l’axe de rotation.', 2),
    ('e1b46eb8-c2d9-5104-b7c6-ced143cd218a'::uuid, '09b673ab-ee83-509e-a407-07676f37f581'::uuid, 'Tous les points d’un solide en rotation ont la même vitesse linéaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils ont la même vitesse ANGULAIRE ; la vitesse linéaire croît avec la distance à l’axe.', 3),
    ('a28a6c6d-f043-559d-b1db-56040902fba5'::uuid, '09b673ab-ee83-509e-a407-07676f37f581'::uuid, 'Un mobile en mouvement circulaire uniforme a-t-il une accélération ?', 'mcq', '["Oui, dirigée vers le centre","Non, sa vitesse est constante","Oui, tangente à la trajectoire","Non, son accélération est nulle par définition"]'::jsonb, 0, 'La direction du vecteur vitesse change en permanence.', 4),
    ('2bb64b9c-47ad-50bc-9cd0-22d5be68df87'::uuid, '09b673ab-ee83-509e-a407-07676f37f581'::uuid, 'Que fait un réducteur au couple transmis ?', 'mcq', '["Il l’augmente dans la même proportion qu’il réduit la vitesse","Il le diminue","Il le laisse inchangé","Il l’annule"]'::jsonb, 0, 'La puissance se conserve, aux pertes près.', 5),
    ('d74697ee-0420-5dae-bb1c-3c19e7cc5c69'::uuid, '09b673ab-ee83-509e-a407-07676f37f581'::uuid, 'Le vecteur vitesse est tangent à la trajectoire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et orienté dans le sens du mouvement.', 6),
    ('c17b30d3-1230-511e-8eb6-a051391f3f00'::uuid, '09b673ab-ee83-509e-a407-07676f37f581'::uuid, 'Quelle est l’unité de la vitesse angulaire dans le Système international ?', 'mcq', '["Le radian par seconde","Le tour par minute","Le mètre par seconde","Le degré par seconde"]'::jsonb, 0, 'Les tours par minute doivent y être convertis avant tout calcul.', 7),
    ('001f43e6-9566-527c-a790-ed395895de09'::uuid, '09b673ab-ee83-509e-a407-07676f37f581'::uuid, 'Dans un mouvement rectiligne uniformément varié, comment varie la position avec le temps ?', 'mcq', '["De façon quadratique","De façon linéaire","De façon constante","De façon exponentielle"]'::jsonb, 0, 'La vitesse, elle, varie linéairement.', 8),
    ('f2760c1f-179d-5817-bb84-481b8fec6af6'::uuid, '2eb9d35d-9584-5591-8762-b37241e72612'::uuid, 'Qu’est-ce qu’un signal logique ?', 'mcq', '["Un signal numérique à deux états seulement","Un signal qui varie continûment","Un signal sans bruit","Un signal de fréquence fixe"]'::jsonb, 0, '0 et 1, correspondant à deux plages de tension.', 1),
    ('d0f4b569-876a-5245-9155-a9286a6d9a4d'::uuid, '2eb9d35d-9584-5591-8762-b37241e72612'::uuid, 'Quelles sont les trois étapes de la conversion analogique-numérique ?', 'mcq', '["Échantillonnage, quantification, codage","Amplification, filtrage, transmission","Mesure, calcul, affichage","Compression, envoi, décompression"]'::jsonb, 0, 'Dans cet ordre, et chacune a son effet propre sur la fidélité.', 2),
    ('381bd12b-7294-5114-be19-7cdb5a53a672'::uuid, '2eb9d35d-9584-5591-8762-b37241e72612'::uuid, 'Quelle doit être au minimum la fréquence d’échantillonnage ?', 'mcq', '["Le double de la plus haute fréquence du signal","La moitié de la fréquence du signal","Égale à la fréquence du signal","Dix fois la fréquence du signal"]'::jsonb, 0, 'En dessous, l’information est irrémédiablement perdue.', 3),
    ('56ffbdfc-e50c-5c04-935b-2872bc5a7e46'::uuid, '2eb9d35d-9584-5591-8762-b37241e72612'::uuid, 'Combien de niveaux permet une quantification sur n bits ?', 'mcq', '["2 puissance n","n","n²","2 × n"]'::jsonb, 0, 'Huit bits donnent 256 niveaux.', 4),
    ('7800e12a-e16a-56bc-8531-4ec00481bfeb'::uuid, '2eb9d35d-9584-5591-8762-b37241e72612'::uuid, 'Un signal numérique se dégrade à chaque copie, comme un signal analogique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se RÉGÉNÈRE exactement tant que le bruit reste sous le seuil de décision.', 5),
    ('d021a86c-2011-5532-a70d-0440567e2d32'::uuid, '2eb9d35d-9584-5591-8762-b37241e72612'::uuid, 'Qu’est-ce que le rapport cyclique d’un signal logique ?', 'mcq', '["La fraction de la période pendant laquelle le signal vaut 1","Le nombre de périodes par seconde","L’amplitude du signal","Le temps de montée"]'::jsonb, 0, 'C’est lui que fait varier une modulation de largeur d’impulsion.', 6),
    ('62e5ce63-b58b-55b1-a13e-41ff0c37bde2'::uuid, '2eb9d35d-9584-5591-8762-b37241e72612'::uuid, 'À quoi sert la modulation de largeur d’impulsion (MLI) ?', 'mcq', '["À régler la puissance moyenne envoyée à un récepteur","À convertir un signal analogique","À corriger les erreurs de transmission","À amplifier un signal faible"]'::jsonb, 0, 'Elle pilote la vitesse d’un moteur ou l’intensité d’une LED.', 7),
    ('cc8f521b-97da-544a-9395-ec44399f0f37'::uuid, '2eb9d35d-9584-5591-8762-b37241e72612'::uuid, 'Augmenter la résolution d’une numérisation augmente la taille du fichier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Fidélité et poids sont l’arbitrage permanent de la numérisation.', 8),
    ('7d0d0682-5c13-5a9b-97fa-94a23d6a0512'::uuid, '156edf51-37ed-5941-8e94-a84329085f0f'::uuid, 'Combien de valeurs différentes un octet peut-il coder ?', 'mcq', '["256","8","128","512"]'::jsonb, 0, 'Huit bits, donc 2 puissance 8 combinaisons.', 1),
    ('a87b5786-4c98-554a-95e5-f0a6a78f6cfa'::uuid, '156edf51-37ed-5941-8e94-a84329085f0f'::uuid, 'À combien de bits correspond un chiffre hexadécimal ?', 'mcq', '["Quatre","Huit","Deux","Seize"]'::jsonb, 0, 'C’est ce qui fait de l’hexadécimal une abréviation commode du binaire.', 2),
    ('c0a03561-f6bb-5d6a-9bd7-543b56762e01'::uuid, '156edf51-37ed-5941-8e94-a84329085f0f'::uuid, 'Que vaut le nombre binaire 1011 en décimal ?', 'mcq', '["11","13","9","7"]'::jsonb, 0, '8 + 0 + 2 + 1 = 11.', 3),
    ('20c4b3a8-7314-55fd-83a8-a0174e0b4f9a'::uuid, '156edf51-37ed-5941-8e94-a84329085f0f'::uuid, 'Le mot binaire lui-même indique ce qu’il représente.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seule la convention d’interprétation, portée par le programme, le dit.', 4),
    ('d2e05642-16ad-5444-8594-35602e1fa8da'::uuid, '156edf51-37ed-5941-8e94-a84329085f0f'::uuid, 'Quel codage a remplacé l’ASCII pour couvrir tous les alphabets ?', 'mcq', '["Unicode, notamment via UTF-8","Le binaire pur","L’hexadécimal","Le code de parité"]'::jsonb, 0, 'L’ASCII sur 7 bits ne suffisait pas aux langues accentuées.', 5),
    ('4bca4018-ad97-5e76-b2ad-626fa2a86db1'::uuid, '156edf51-37ed-5941-8e94-a84329085f0f'::uuid, 'Combien de valeurs code un mot de n bits ?', 'mcq', '["2 puissance n","n puissance 2","2 × n","n / 2"]'::jsonb, 0, 'Relation à savoir utiliser dans les deux sens.', 6),
    ('87e31048-38df-521d-b491-b1c2888f10c3'::uuid, '156edf51-37ed-5941-8e94-a84329085f0f'::uuid, 'Un bit de parité permet de corriger une erreur de transmission.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il permet de la DÉTECTER ; corriger exige un code correcteur.', 7),
    ('a1b91809-25b4-54a9-a1fa-7ce246714e85'::uuid, '156edf51-37ed-5941-8e94-a84329085f0f'::uuid, 'Comment convertit-on un nombre décimal en binaire ?', 'mcq', '["Par divisions successives par 2, en lisant les restes de bas en haut","En multipliant par 2","En le divisant par 16","En ajoutant les puissances de 10"]'::jsonb, 0, 'L’ordre de lecture des restes est le piège habituel.', 8),
    ('2a039cd0-304d-53aa-b7ba-e347bd2775a3'::uuid, 'b616610f-6745-5c7d-a5da-0280774398c9'::uuid, 'Quand la sortie d’un opérateur ET vaut-elle 1 ?', 'mcq', '["Seulement si toutes les entrées valent 1","Si au moins une entrée vaut 1","Si les entrées sont différentes","Si toutes les entrées valent 0"]'::jsonb, 0, 'C’est l’opérateur des conditions simultanées.', 1),
    ('674afb15-1515-5959-ab36-2eb893f8b85f'::uuid, 'b616610f-6745-5c7d-a5da-0280774398c9'::uuid, 'Le OU logique est-il inclusif ou exclusif ?', 'mcq', '["Inclusif : 1 OU 1 vaut 1","Exclusif : 1 OU 1 vaut 0","Cela dépend du circuit","Il n’a pas de valeur pour 1 OU 1"]'::jsonb, 0, 'Le OU EXCLUSIF, lui, vaut 1 quand les entrées diffèrent.', 2),
    ('d3cb7e42-6bda-5e87-b294-60770cb071db'::uuid, 'b616610f-6745-5c7d-a5da-0280774398c9'::uuid, 'Combien de lignes compte la table de vérité d’une fonction à trois entrées ?', 'mcq', '["Huit","Six","Trois","Neuf"]'::jsonb, 0, '2 puissance 3 combinaisons possibles.', 3),
    ('73730835-d2e8-59f1-ac56-b4012cd4de74'::uuid, 'b616610f-6745-5c7d-a5da-0280774398c9'::uuid, 'Pourquoi l’opérateur NON-ET est-il dit universel ?', 'mcq', '["Parce qu’il permet de reconstruire toutes les autres fonctions logiques","Parce qu’il est le plus rapide","Parce qu’il consomme moins","Parce qu’il a une seule entrée"]'::jsonb, 0, 'C’est pourquoi l’industrie le fabrique en masse.', 4),
    ('451f8d07-1ead-56ac-bd19-0dd01267ddbf'::uuid, 'b616610f-6745-5c7d-a5da-0280774398c9'::uuid, 'Quand la sortie d’un OU EXCLUSIF vaut-elle 1 ?', 'mcq', '["Quand les entrées sont différentes","Quand les entrées sont identiques","Quand les deux valent 1","Quand les deux valent 0"]'::jsonb, 0, 'Il sert dans les additionneurs et les codes correcteurs.', 5),
    ('8bcb2d80-f85e-5763-b173-8d2646addb56'::uuid, 'b616610f-6745-5c7d-a5da-0280774398c9'::uuid, 'La sortie d’un opérateur NON est l’inverse de son entrée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le seul opérateur fondamental à une seule entrée.', 6),
    ('eeacaf24-b987-5d3e-89ef-aeef3a513e08'::uuid, 'b616610f-6745-5c7d-a5da-0280774398c9'::uuid, 'Que vaut la sortie d’un NON-OU dont les deux entrées valent 0 ?', 'mcq', '["1","0","Indéterminée","Cela dépend du circuit"]'::jsonb, 0, 'Le OU donnerait 0 ; le NON-OU l’inverse.', 7),
    ('231401cb-e87b-5cf4-8abb-67dda2e34e6b'::uuid, 'b616610f-6745-5c7d-a5da-0280774398c9'::uuid, 'Un dispositif de sécurité à deux boutons à presser simultanément utilise un opérateur ET.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Toutes les conditions doivent être réunies pour autoriser le démarrage.', 8),
    ('c01c5416-ddeb-5175-af35-ab8c52833ffc'::uuid, '1d37372b-a673-57c6-8725-33ec7968e889'::uuid, 'Quelles sont les trois représentations équivalentes d’une fonction logique ?', 'mcq', '["Table de vérité, équation logique et logigramme","Schéma, plan et notice","Diagramme d’états, de blocs et de séquence","Binaire, décimal et hexadécimal"]'::jsonb, 0, 'Savoir passer de l’une à l’autre est la compétence centrale.', 1),
    ('7dd6e666-5e4f-58d7-a5b2-4a01ce231aa0'::uuid, '1d37372b-a673-57c6-8725-33ec7968e889'::uuid, 'Dans la méthode de la somme de produits, quelles lignes retient-on ?', 'mcq', '["Celles où la sortie vaut 1","Celles où la sortie vaut 0","Toutes les lignes","La première et la dernière"]'::jsonb, 0, 'La méthode du produit de sommes part, elle, des lignes à 0.', 2),
    ('03f5435d-07c1-54b6-9934-e16e23e1511e'::uuid, '1d37372b-a673-57c6-8725-33ec7968e889'::uuid, 'Quel est l’ordre de priorité des opérations logiques ?', 'mcq', '["Complément, puis ET, puis OU","OU, puis ET, puis complément","ET, puis OU, puis complément","Toutes au même niveau"]'::jsonb, 0, 'Une équation mal parenthésée donne un montage faux.', 3),
    ('fd1f05d9-18d4-5d2c-8b6a-afedb889aac0'::uuid, '1d37372b-a673-57c6-8725-33ec7968e889'::uuid, 'Un même comportement logique n’admet qu’un seul logigramme possible.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Plusieurs montages équivalents existent, de coûts et de lisibilité différents.', 4),
    ('9af48455-f647-5e3c-85d9-39b79182c282'::uuid, '1d37372b-a673-57c6-8725-33ec7968e889'::uuid, 'Comment analyse-t-on un logigramme fourni sans explication ?', 'mcq', '["En nommant les sorties intermédiaires porte par porte, puis en remontant","En comptant les portes","En mesurant les tensions","En simulant au hasard"]'::jsonb, 0, 'On dresse ensuite la table de vérité pour vérifier.', 5),
    ('e9690ae9-1a37-5dec-8319-72de7ea87ab5'::uuid, '1d37372b-a673-57c6-8725-33ec7968e889'::uuid, 'Où se trouvent les entrées sur un logigramme normalisé ?', 'mcq', '["À gauche","À droite","En bas","Au centre"]'::jsonb, 0, 'La sortie est à droite : le sens de lecture est toujours le même.', 6),
    ('2983b1d8-9554-5744-971b-81b04950bb74'::uuid, '1d37372b-a673-57c6-8725-33ec7968e889'::uuid, 'Pourquoi la somme de produits est-elle la méthode la plus employée ?', 'mcq', '["Parce qu’il y a en général moins de 1 que de 0 dans une table","Parce qu’elle est plus rigoureuse","Parce qu’elle évite les portes NON","Parce qu’elle donne toujours le montage le moins cher"]'::jsonb, 0, 'Elle se lit aussi plus directement depuis la table.', 7),
    ('5cc6ffd4-55e6-57f4-8ee3-315c26770697'::uuid, '1d37372b-a673-57c6-8725-33ec7968e889'::uuid, 'Le choix du logigramme le moins coûteux dépend des portes disponibles dans le boîtier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un montage n’utilisant qu’un type de porte peut être préférable en pratique.', 8),
    ('37c726c7-fe20-5cfa-897d-3ecd6ae271e6'::uuid, '2899dea6-971c-5b9a-a19a-6894026b7f2f'::uuid, 'Que vaut a + complément de a ?', 'mcq', '["1","0","a","Le complément de a"]'::jsonb, 0, 'C’est la règle de complémentarité, qui simplifie le plus souvent.', 1),
    ('699acd67-4aae-5083-a20f-e423c3e89708'::uuid, '2899dea6-971c-5b9a-a19a-6894026b7f2f'::uuid, 'Que vaut a + 1 en algèbre de Boole ?', 'mcq', '["1","a","0","2"]'::jsonb, 0, 'Le 1 est absorbant pour le OU.', 2),
    ('9be2eacc-aabc-56a6-b502-8a5a72919153'::uuid, '2899dea6-971c-5b9a-a19a-6894026b7f2f'::uuid, 'En algèbre de Boole, le OU est distributif sur le ET.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'a + (b . c) = (a + b) . (a + c) : cette égalité serait fausse avec des nombres.', 3),
    ('443f11b8-e1a4-59bb-bd29-9f97220793e2'::uuid, '2899dea6-971c-5b9a-a19a-6894026b7f2f'::uuid, 'Que donne la loi de De Morgan appliquée au complément de (a . b) ?', 'mcq', '["Complément de a + complément de b","Complément de a . complément de b","a + b","a . b"]'::jsonb, 0, 'On complémente chaque terme et on échange les opérateurs.', 4),
    ('9363eec9-b69d-5b08-9b82-1171f818f0cb'::uuid, '2899dea6-971c-5b9a-a19a-6894026b7f2f'::uuid, 'Que vaut a . a en algèbre de Boole ?', 'mcq', '["a","a²","0","1"]'::jsonb, 0, 'C’est l’idempotence : une variable ET elle-même ne change rien.', 5),
    ('d22e17ff-f0c7-5783-9e86-4665f26d6513'::uuid, '2899dea6-971c-5b9a-a19a-6894026b7f2f'::uuid, 'À quoi servent principalement les lois de De Morgan ?', 'mcq', '["À transformer un montage pour n’employer qu’un seul type de porte","À calculer une table de vérité","À convertir en hexadécimal","À mesurer un signal"]'::jsonb, 0, 'Un montage tout en NON-ET, par exemple.', 6),
    ('c74931cd-4b4d-55a1-8dea-4ae9edf941dc'::uuid, '2899dea6-971c-5b9a-a19a-6894026b7f2f'::uuid, 'Que vaut a + (a . b) ?', 'mcq', '["a","a . b","b","1"]'::jsonb, 0, 'C’est le théorème d’absorption, qui élimine des termes entiers.', 7),
    ('eb5c99a6-7764-5ee7-8d70-3e112b1b863b'::uuid, '2899dea6-971c-5b9a-a19a-6894026b7f2f'::uuid, 'Le complément du complément de a vaut le complément de a.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il vaut a : c’est la propriété d’involution.', 8),
    ('352a178a-05af-5e15-aefc-393956b6c733'::uuid, 'a6785078-95fc-51cc-8baa-eea079307d22'::uuid, 'Pourquoi simplifie-t-on une expression logique ?', 'mcq', '["Pour réduire le nombre de portes, donc le coût et la consommation","Pour changer la fonction réalisée","Pour augmenter la vitesse du signal","Pour éviter les tables de vérité"]'::jsonb, 0, 'Moins de composants, moins de place, moins de pannes possibles.', 1),
    ('1d7de8e5-8b14-5ec4-a1fd-2592957844ea'::uuid, 'a6785078-95fc-51cc-8baa-eea079307d22'::uuid, 'Pourquoi les en-têtes d’un tableau de Karnaugh suivent-ils un code de Gray ?', 'mcq', '["Pour que deux cases voisines ne diffèrent que par une seule variable","Pour économiser de la place","Par convention historique","Pour respecter l’ordre binaire"]'::jsonb, 0, 'C’est la propriété qui rend les regroupements valides.', 2),
    ('b78660b5-b1e6-5b8c-85d6-6e1f8c885621'::uuid, 'a6785078-95fc-51cc-8baa-eea079307d22'::uuid, 'Quelle doit être la taille d’un groupe dans un tableau de Karnaugh ?', 'mcq', '["Une puissance de 2","Un nombre pair quelconque","Trois cases au minimum","Toujours quatre cases"]'::jsonb, 0, '1, 2, 4, 8… et aussi grands que possible.', 3),
    ('68eb0866-bba8-5bc3-8254-00f5a3a5f2f2'::uuid, 'a6785078-95fc-51cc-8baa-eea079307d22'::uuid, 'Les groupes d’un tableau de Karnaugh peuvent se chevaucher.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et il faut les faire aussi grands que possible, quitte à les superposer.', 4),
    ('3bc4688b-b46d-5142-a025-b4a2e69cfc02'::uuid, 'a6785078-95fc-51cc-8baa-eea079307d22'::uuid, 'Les cases des bords gauche et droit d’un tableau de Karnaugh sont-elles voisines ?', 'mcq', '["Oui, le tableau se referme sur lui-même","Non, jamais","Seulement pour trois variables","Seulement si la sortie vaut 1"]'::jsonb, 0, 'Comme celles du haut et du bas.', 5),
    ('04c8c2b5-c45a-52c5-b25b-3efd3e929994'::uuid, 'a6785078-95fc-51cc-8baa-eea079307d22'::uuid, 'Que garde-t-on d’un groupe pour écrire son terme ?', 'mcq', '["Les variables qui restent constantes dans tout le groupe","Toutes les variables","La variable la plus fréquente","Aucune variable"]'::jsonb, 0, 'Un groupe deux fois plus grand élimine une variable de plus.', 6),
    ('d7369cd6-2af1-5384-9291-b1c467a08755'::uuid, 'a6785078-95fc-51cc-8baa-eea079307d22'::uuid, 'Comment utilise-t-on les cas indifférents dans un tableau de Karnaugh ?', 'mcq', '["Librement, en les incluant s’ils agrandissent un groupe","On les traite toujours comme des 0","On les traite toujours comme des 1","On les supprime du tableau"]'::jsonb, 0, 'Ce sont des combinaisons qui ne peuvent pas se produire : un cadeau pour simplifier.', 7),
    ('fd6fc815-accd-51dc-ace9-eb2bd0314864'::uuid, 'a6785078-95fc-51cc-8baa-eea079307d22'::uuid, 'Former de petits groupes plutôt qu’un grand donne un résultat faux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le résultat reste juste, mais l’expression n’est pas simplifiée au maximum.', 8),
    ('a4520afe-aad5-55f5-925b-edfe7172913a'::uuid, '6e545dd4-12cc-565f-85e7-a076d1ae674c'::uuid, 'Quelles sont les trois exigences fondamentales de la sécurité d’une transmission ?', 'mcq', '["Intégrité, confidentialité et disponibilité","Vitesse, coût et fiabilité","Chiffrement, hachage et compression","Émission, transport et réception"]'::jsonb, 0, 'Authentification et non-répudiation viennent s’y ajouter.', 1),
    ('fbecb857-cc30-533c-b86c-5fe1785f45de'::uuid, '6e545dd4-12cc-565f-85e7-a076d1ae674c'::uuid, 'Qu’est-ce que le chiffrement asymétrique ?', 'mcq', '["Une clé publique pour chiffrer, une clé privée pour déchiffrer","La même clé pour chiffrer et déchiffrer","Un chiffrement sans clé","Un chiffrement à clé variable dans le temps"]'::jsonb, 0, 'Il résout le problème de la transmission de la clé.', 2),
    ('565d93d5-12e8-5c7b-b5e0-6465e705aca5'::uuid, '6e545dd4-12cc-565f-85e7-a076d1ae674c'::uuid, 'Le chiffrement symétrique est plus rapide que l’asymétrique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est pourquoi on combine les deux : l’asymétrique transmet la clé de session.', 3),
    ('76f55e13-a274-56bb-bdb6-c489a169c73f'::uuid, '6e545dd4-12cc-565f-85e7-a076d1ae674c'::uuid, 'Que garantit une signature numérique ?', 'mcq', '["L’authentification et la non-répudiation, pas la confidentialité","La confidentialité du message","La disponibilité du service","La compression des données"]'::jsonb, 0, 'Le message signé peut rester parfaitement lisible.', 4),
    ('9bd0209f-d6c4-5b14-9b99-4dab49fd4706'::uuid, '6e545dd4-12cc-565f-85e7-a076d1ae674c'::uuid, 'Qu’est-ce qu’une fonction de hachage ?', 'mcq', '["Une fonction produisant une empreinte de taille fixe, très sensible à toute modification","Un algorithme de chiffrement réversible","Une méthode de compression","Un protocole de transmission"]'::jsonb, 0, 'La moindre modification du message change entièrement l’empreinte.', 5),
    ('8eae3d16-9620-58d9-bf34-50f828be7ef5'::uuid, '6e545dd4-12cc-565f-85e7-a076d1ae674c'::uuid, 'Quand un code correcteur est-il indispensable plutôt qu’un simple détecteur ?', 'mcq', '["Quand aucune retransmission n’est possible","Quand le message est court","Quand le canal est rapide","Quand le message est chiffré"]'::jsonb, 0, 'Une sonde spatiale ou un disque optique rayé, par exemple.', 6),
    ('f182abb7-20c2-5500-b8b2-fc4ee409db22'::uuid, '6e545dd4-12cc-565f-85e7-a076d1ae674c'::uuid, 'Avec quelle clé l’émetteur signe-t-il un message ?', 'mcq', '["Sa clé privée","Sa clé publique","La clé publique du destinataire","Une clé symétrique partagée"]'::jsonb, 0, 'Chacun vérifie ensuite avec sa clé publique.', 7),
    ('5bce94c8-13ca-5f0c-8e8b-dd59d19bf37e'::uuid, '6e545dd4-12cc-565f-85e7-a076d1ae674c'::uuid, 'Chiffrer un message garantit aussi l’identité de son émetteur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le chiffrement protège le CONTENU ; la signature garantit l’ORIGINE.', 8),
    ('bfb65ce5-d0f7-5015-b012-5ab7e3df86a5'::uuid, '234b91e3-be5e-5777-b4e5-60466328693f'::uuid, 'Quelle différence entre une adresse MAC et une adresse IP ?', 'mcq', '["La MAC est physique et fixe, l’IP est logique et attribuée par le réseau","La MAC est attribuée par le réseau, l’IP par le constructeur","Elles sont identiques","La MAC désigne l’application, l’IP la machine"]'::jsonb, 0, 'L’adresse IP situe la machine dans le réseau, comme une adresse postale.', 1),
    ('30a67b49-e77c-56ca-a54d-5c73b5cafae7'::uuid, '234b91e3-be5e-5777-b4e5-60466328693f'::uuid, 'Quel protocole garantit la remise dans l’ordre et la retransmission des paquets perdus ?', 'mcq', '["TCP","UDP","IP","Ethernet"]'::jsonb, 0, 'UDP, plus rapide, n’offre aucune de ces garanties.', 2),
    ('f6dcda85-07d4-51c6-8fc4-68ddde66efb7'::uuid, '234b91e3-be5e-5777-b4e5-60466328693f'::uuid, 'Pourquoi préfère-t-on UDP pour la voix en direct ?', 'mcq', '["Parce qu’un paquet retransmis arriverait trop tard pour servir","Parce qu’il est plus fiable","Parce qu’il chiffre les données","Parce qu’il consomme moins de bande passante que tout autre"]'::jsonb, 0, 'La rapidité y prime sur l’exhaustivité.', 3),
    ('c7f27554-66be-57f1-b611-40ec913c5192'::uuid, '234b91e3-be5e-5777-b4e5-60466328693f'::uuid, 'À quoi sert le masque de sous-réseau ?', 'mcq', '["À séparer la partie réseau de la partie machine dans une adresse IP","À chiffrer les communications","À attribuer les adresses MAC","À compter les équipements connectés"]'::jsonb, 0, 'Il détermine si deux machines communiquent directement ou via un routeur.', 4),
    ('79e709c7-6102-5d5d-bc8d-627c77b01cb5'::uuid, '234b91e3-be5e-5777-b4e5-60466328693f'::uuid, 'Que désigne un numéro de port ?', 'mcq', '["L’application destinataire sur la machine","La machine sur le réseau","La carte réseau","Le réseau lui-même"]'::jsonb, 0, 'L’adresse IP situe la machine, le port l’application.', 5),
    ('cf0d99fd-9f1f-539f-bb9e-66f9bd6160b8'::uuid, '234b91e3-be5e-5777-b4e5-60466328693f'::uuid, 'Dans une topologie en étoile, la panne du nœud central n’affecte qu’une branche.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle affecte TOUT le réseau ; c’est la panne d’une branche qui reste isolée.', 6),
    ('ec229282-e289-59b3-98ca-bbb532b6200c'::uuid, '234b91e3-be5e-5777-b4e5-60466328693f'::uuid, 'Quel équipement relie deux réseaux différents et choisit le chemin ?', 'mcq', '["Le routeur","Le commutateur","Le point d’accès","Le répéteur"]'::jsonb, 0, 'Le commutateur, lui, distribue les trames à l’intérieur d’un même réseau local.', 7),
    ('d27639af-0029-5b42-9da1-c9578a94c597'::uuid, '234b91e3-be5e-5777-b4e5-60466328693f'::uuid, 'Quel est l’intérêt d’organiser les protocoles en couches ?', 'mcq', '["Chaque couche peut évoluer sans que les autres soient réécrites","Cela accélère la transmission","Cela réduit le nombre d’adresses nécessaires","Cela chiffre automatiquement les données"]'::jsonb, 0, 'Le Wi-Fi a remplacé le câble sans qu’HTTP change d’une ligne.', 8),
    ('d8337d41-0b91-5f26-8552-311150edd6d2'::uuid, '979cbc2b-1f29-5499-8e65-edb96b712d4a'::uuid, 'Comment se branche un ampèremètre ?', 'mcq', '["En série dans la branche à mesurer","En dérivation aux bornes du dipôle","À la place du générateur","Peu importe"]'::jsonb, 0, 'En dérivation, sa résistance quasi nulle court-circuiterait le dipôle.', 1),
    ('6e40e137-049a-5909-83ab-123a9cd92fcf'::uuid, '979cbc2b-1f29-5499-8e65-edb96b712d4a'::uuid, 'Que dit la loi des nœuds ?', 'mcq', '["La somme des intensités entrantes égale la somme des sortantes","La somme des tensions d’une maille est nulle","L’intensité est la même partout","La tension est la même partout"]'::jsonb, 0, 'C’est la conservation de la charge électrique.', 2),
    ('4269ea1f-f582-5655-b595-71387a679bbf'::uuid, '979cbc2b-1f29-5499-8e65-edb96b712d4a'::uuid, 'Que dit la loi des mailles ?', 'mcq', '["La somme algébrique des tensions le long d’un parcours fermé est nulle","Les intensités s’additionnent","Les résistances s’additionnent","La puissance se conserve"]'::jsonb, 0, 'En revenant au point de départ, on retrouve le même potentiel.', 3),
    ('b8458d19-72e4-501e-a79c-40cd44149d07'::uuid, '979cbc2b-1f29-5499-8e65-edb96b712d4a'::uuid, 'En dérivation, la tension est la même aux bornes de chaque branche.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ce sont les intensités qui s’additionnent.', 4),
    ('28426d18-916f-5598-89e7-d26d69b70e90'::uuid, '979cbc2b-1f29-5499-8e65-edb96b712d4a'::uuid, 'Comment se combinent deux résistances en série ?', 'mcq', '["Elles s’additionnent","Leurs inverses s’additionnent","On prend la plus grande","On prend leur moyenne"]'::jsonb, 0, 'En dérivation, ce sont leurs inverses qui s’additionnent.', 5),
    ('7de28450-d790-59b1-898d-2b97ef4e6cd0'::uuid, '979cbc2b-1f29-5499-8e65-edb96b712d4a'::uuid, 'À quoi sert un pont diviseur de tension ?', 'mcq', '["À adapter un signal, par exemple à l’entrée d’un microcontrôleur","À mesurer une intensité","À produire un courant continu","À stocker de l’énergie"]'::jsonb, 0, 'Deux résistances en série partagent la tension proportionnellement.', 6),
    ('da6a24d4-f7e9-558e-b351-13f520d40ad7'::uuid, '979cbc2b-1f29-5499-8e65-edb96b712d4a'::uuid, 'Pourquoi les installations domestiques sont-elles câblées en dérivation ?', 'mcq', '["Pour qu’une branche coupée n’arrête pas les autres","Pour économiser du câble","Pour augmenter la tension","Pour réduire l’intensité totale"]'::jsonb, 0, 'En série, une seule coupure arrêterait toute l’installation.', 7),
    ('db76ae8e-37ca-523f-9305-4ce410f853ac'::uuid, '979cbc2b-1f29-5499-8e65-edb96b712d4a'::uuid, 'Le sens conventionnel du courant va du moins vers le plus à l’extérieur du générateur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il va du PLUS vers le MOINS à l’extérieur du générateur.', 8),
    ('4fc79ce9-f707-5cb6-bb78-d75e6a8bf407'::uuid, '7b0ec4f9-93c5-565a-82dd-7dfc8eccf36a'::uuid, 'Quelle relation modélise un générateur réel ?', 'mcq', '["U = E − r × I","U = E + r × I","U = R × I","U = E × I"]'::jsonb, 0, 'r est la résistance interne : la tension chute quand le courant augmente.', 1),
    ('8f12e51a-0541-59cf-8879-0adc5289046d'::uuid, '7b0ec4f9-93c5-565a-82dd-7dfc8eccf36a'::uuid, 'Quelle est l’unité de la capacité d’un condensateur ?', 'mcq', '["Le farad","L’ohm","Le henry","Le coulomb"]'::jsonb, 0, 'Q = C × U, avec Q en coulombs et U en volts.', 2),
    ('4a881004-02ea-5ae1-b4af-0519c46ced40'::uuid, '7b0ec4f9-93c5-565a-82dd-7dfc8eccf36a'::uuid, 'Un condensateur laisse passer le courant continu en régime établi.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se comporte alors comme un interrupteur ouvert.', 3),
    ('a1806aa3-78e0-5d29-b782-639a4f1ee22d'::uuid, '7b0ec4f9-93c5-565a-82dd-7dfc8eccf36a'::uuid, 'Que vaut la constante de temps de la charge d’un condensateur à travers une résistance ?', 'mcq', '["τ = R × C","τ = R / C","τ = C / R","τ = R × C²"]'::jsonb, 0, 'Le régime est établi à environ 99 % au bout de 5 τ.', 4),
    ('4bb7fe9d-cb88-5474-a2e4-c963637d8031'::uuid, '7b0ec4f9-93c5-565a-82dd-7dfc8eccf36a'::uuid, 'Quelle propriété du condensateur est la plus utilisée en électronique ?', 'mcq', '["La tension à ses bornes ne peut pas varier brusquement","Il produit du courant","Il chauffe peu","Il inverse la tension"]'::jsonb, 0, 'D’où ses usages de filtrage, de temporisation et de découplage.', 5),
    ('45e1e888-128a-58ed-8cbb-853b550927be'::uuid, '7b0ec4f9-93c5-565a-82dd-7dfc8eccf36a'::uuid, 'Pourquoi place-t-on une résistance en série avec une LED ?', 'mcq', '["Pour limiter le courant qui la traverse","Pour augmenter sa luminosité","Pour la refroidir","Pour inverser sa polarité"]'::jsonb, 0, 'Sans elle, la LED grille immédiatement.', 6),
    ('512de3da-897a-52f7-9238-78983c2ef29b'::uuid, '7b0ec4f9-93c5-565a-82dd-7dfc8eccf36a'::uuid, 'Quelle est l’expression de l’énergie stockée dans un condensateur ?', 'mcq', '["E = ½ × C × U²","E = C × U","E = ½ × C × U","E = C × U²"]'::jsonb, 0, 'Elle croît avec le carré de la tension.', 7),
    ('f14676a0-0f53-5f99-8fc7-d4dec3a62261'::uuid, '7b0ec4f9-93c5-565a-82dd-7dfc8eccf36a'::uuid, 'La résistance d’une thermistance varie avec la température.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce qui en fait un capteur de température très répandu.', 8),
    ('7cc99b1b-30b1-5bfa-b195-b3cdf797e3ad'::uuid, 'ab225d5d-6ba6-5af7-b568-c8cb6cb8306d'::uuid, 'Quelle grandeur ne peut pas varier brusquement dans une bobine ?', 'mcq', '["Le courant qui la traverse","La tension à ses bornes","Sa résistance","Son inductance"]'::jsonb, 0, 'C’est le comportement symétrique de celui du condensateur.', 1),
    ('8cc43db2-41fc-5d6e-82a6-0dc371a9c799'::uuid, 'ab225d5d-6ba6-5af7-b568-c8cb6cb8306d'::uuid, 'À quoi sert une diode de roue libre ?', 'mcq', '["À évacuer le courant d’une bobine coupée, évitant une surtension destructrice","À redresser un courant alternatif","À limiter la luminosité d’une LED","À mesurer un courant"]'::jsonb, 0, 'Elle protège le transistor de commande.', 2),
    ('7f9d09d3-5021-52ac-925a-72883fe65714'::uuid, 'ab225d5d-6ba6-5af7-b568-c8cb6cb8306d'::uuid, 'Quelle est la tension de seuil approximative d’une diode au silicium ?', 'mcq', '["Environ 0,7 V","Environ 5 V","Environ 0,1 V","Environ 12 V"]'::jsonb, 0, 'En dessous, elle ne conduit pas en direct.', 3),
    ('53f97d38-1da0-5853-9c06-c7983a91df6c'::uuid, 'ab225d5d-6ba6-5af7-b568-c8cb6cb8306d'::uuid, 'Une diode laisse passer le courant dans les deux sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle conduit en direct et bloque en inverse : c’est sa raison d’être.', 4),
    ('68e140da-21ba-5738-a058-57e3addb270f'::uuid, 'ab225d5d-6ba6-5af7-b568-c8cb6cb8306d'::uuid, 'Que fait un transistor en régime de commutation ?', 'mcq', '["Il fonctionne en tout ou rien, bloqué ou saturé","Il amplifie proportionnellement le signal","Il stocke de l’énergie","Il redresse le courant"]'::jsonb, 0, 'C’est le régime de toute l’électronique numérique.', 5),
    ('2af24193-82b4-5bca-9cba-384226bb3ae7'::uuid, 'ab225d5d-6ba6-5af7-b568-c8cb6cb8306d'::uuid, 'Un transistor fournit l’énergie au circuit qu’il commande.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il la MODULE : la puissance vient de l’alimentation.', 6),
    ('dbbcf4ad-3fe1-58fc-ba11-7d1f639a4313'::uuid, 'ab225d5d-6ba6-5af7-b568-c8cb6cb8306d'::uuid, 'Quelle est l’expression de l’énergie stockée dans une bobine ?', 'mcq', '["E = ½ × L × I²","E = ½ × L × U²","E = L × I","E = L × I²"]'::jsonb, 0, 'Symétrique de celle du condensateur, avec le courant à la place de la tension.', 7),
    ('f93ab674-c5a3-51d3-94bf-3ce2d2563f75'::uuid, 'ab225d5d-6ba6-5af7-b568-c8cb6cb8306d'::uuid, 'Pourquoi un microcontrôleur a-t-il besoin d’un transistor pour piloter un moteur ?', 'mcq', '["Parce qu’il ne délivre que quelques milliampères","Parce qu’il ne délivre pas de tension","Parce que le moteur est analogique","Parce que le moteur inverse la polarité"]'::jsonb, 0, 'Le transistor commande un courant fort avec un signal faible.', 8),
    ('f153d894-9802-56ab-8b77-8cff5c7ceaf5'::uuid, '2f824104-6f9e-5d3c-8cf4-c5a49b46e663'::uuid, 'Quel appareil montre la forme d’un signal en fonction du temps ?', 'mcq', '["L’oscilloscope","Le multimètre","L’ampèremètre","Le générateur de fonctions"]'::jsonb, 0, 'Le multimètre ne donne qu’une valeur, jamais une allure.', 1),
    ('59672245-5df5-587e-a547-29a138716cc6'::uuid, '2f824104-6f9e-5d3c-8cf4-c5a49b46e663'::uuid, 'Quels sont les deux réglages essentiels d’un oscilloscope ?', 'mcq', '["La base de temps et la sensibilité verticale","La fréquence et la puissance","L’intensité et la résistance","Le calibre et la polarité"]'::jsonb, 0, 'En s/div et en V/div : ce sont eux qui permettent de lire l’écran.', 2),
    ('140e1f44-69f7-5b30-ac65-a22a264bb57b'::uuid, '2f824104-6f9e-5d3c-8cf4-c5a49b46e663'::uuid, 'Une période occupe 4 divisions réglées à 2 ms/div : quelle est la fréquence ?', 'mcq', '["125 Hz","8 Hz","500 Hz","250 Hz"]'::jsonb, 0, 'La période vaut 8 ms, donc f = 1 / 0,008 = 125 Hz.', 3),
    ('0faa515b-13c6-5106-a26b-51cc900dfb49'::uuid, '2f824104-6f9e-5d3c-8cf4-c5a49b46e663'::uuid, 'Comment mesure-t-on une résistance au multimètre ?', 'mcq', '["Hors tension, sur le composant isolé du circuit","En série, circuit alimenté","En dérivation, circuit alimenté","Avec un oscilloscope"]'::jsonb, 0, 'Le reste du circuit fausserait sinon la mesure.', 4),
    ('26186bda-fe67-5235-b893-5f831e03b1ca'::uuid, '2f824104-6f9e-5d3c-8cf4-c5a49b46e663'::uuid, 'Une simulation prend en compte tous les phénomènes réels d’un circuit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle ne connaît que ce qui est modélisé : parasites et tolérances en sont souvent absents.', 5),
    ('3a00c9e8-83ac-5ee1-bc2a-89b208723530'::uuid, '2f824104-6f9e-5d3c-8cf4-c5a49b46e663'::uuid, 'Que traduit un écart entre simulation et mesure ?', 'mcq', '["Un phénomène réel non modélisé ou un composant hors tolérance","Une erreur de calcul","Un cahier des charges mal écrit","Une panne du simulateur"]'::jsonb, 0, 'L’écart calcul/simulation, lui, signale une erreur de modèle ou d’hypothèse.', 6),
    ('c4b8b4cd-4fba-593e-8373-02b9bcce1908'::uuid, '2f824104-6f9e-5d3c-8cf4-c5a49b46e663'::uuid, 'Un écart mesuré est un échec de la conception.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une information ; ne pas le mesurer serait la vraie faute.', 7),
    ('46baae17-034c-52bd-a368-50d49812e6ec'::uuid, '2f824104-6f9e-5d3c-8cf4-c5a49b46e663'::uuid, 'À quoi sert un générateur de fonctions ?', 'mcq', '["À fournir des signaux d’essai calibrés","À mesurer une tension","À alimenter le circuit en continu uniquement","À afficher un oscillogramme"]'::jsonb, 0, 'Sinusoïdal, carré ou triangulaire, de fréquence et d’amplitude réglables.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('si');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('si')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 272 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 272 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
